const monthlyRevenue = `-- name: MonthlyRevenue :many
WITH monthly AS (
  SELECT date_trunc('month', published) AS month, genre, sum(price) AS revenue, count(*) AS n
  FROM books
  WHERE published IS NOT NULL
  GROUP BY 1, 2
)
SELECT month, genre, revenue, n,
       sum(revenue) OVER (PARTITION BY genre ORDER BY month) AS running,
       row_number() OVER (ORDER BY revenue DESC) AS rank
FROM monthly
ORDER BY month, genre;
`

type MonthlyRevenueRow struct {
	Month   *time.Time `json:"month"`
	Genre   Genre      `json:"genre"`
	Revenue *string    `json:"revenue"`
	N       int64      `json:"n"`
	Running *string    `json:"running"`
	Rank    int64      `json:"rank"`
}

func (q *Queries) MonthlyRevenue(ctx context.Context) ([]MonthlyRevenueRow, error) {
	rows, err := q.db.QueryContext(ctx, monthlyRevenue)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []MonthlyRevenueRow
	for rows.Next() {
		var i MonthlyRevenueRow
		if err := rows.Scan(
			&i.Month,
			&i.Genre,
			duckdbDecimal(&i.Revenue),
			&i.N,
			duckdbDecimal(&i.Running),
			&i.Rank,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

