const searchBooks = `-- name: SearchBooks :many
SELECT id, title, price FROM books
WHERE ($1::genre IS NULL OR genre = $1)
  AND price BETWEEN $2 AND $3
  AND title ILIKE '%' || $4 || '%';
`

type SearchBooksParams struct {
	Genre    *Genre `json:"genre"`
	MinPrice string `json:"min_price"`
	MaxPrice string `json:"max_price"`
	Q        string `json:"q"`
}

type SearchBooksRow struct {
	ID    int64  `json:"id"`
	Title string `json:"title"`
	Price string `json:"price"`
}

func (q *Queries) SearchBooks(ctx context.Context, arg SearchBooksParams) ([]SearchBooksRow, error) {
	rows, err := q.db.QueryContext(ctx, searchBooks,
		arg.Genre,
		arg.MinPrice,
		arg.MaxPrice,
		arg.Q,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []SearchBooksRow
	for rows.Next() {
		var i SearchBooksRow
		if err := rows.Scan(&i.ID, &i.Title, duckdbDecimal(&i.Price)); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const updateAuthorBio = `-- name: UpdateAuthorBio :execrows
UPDATE authors SET bio = $1, updated_at = now() WHERE id = $2;
`

type UpdateAuthorBioParams struct {
	Bio *string `json:"bio"`
	ID  int32   `json:"id"`
}

func (q *Queries) UpdateAuthorBio(ctx context.Context, arg UpdateAuthorBioParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, updateAuthorBio, arg.Bio, arg.ID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

const upsertAuthor = `-- name: UpsertAuthor :one
INSERT INTO authors (id, name, bio, email)
VALUES ($1, $2, $3, $4)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, bio = EXCLUDED.bio, updated_at = now()
RETURNING id, name, updated_at;
`

type UpsertAuthorParams struct {
	ID    int32   `json:"id"`
	Name  string  `json:"name"`
	Bio   *string `json:"bio"`
	Email *string `json:"email"`
}

type UpsertAuthorRow struct {
	ID        int32      `json:"id"`
	Name      string     `json:"name"`
	UpdatedAt *time.Time `json:"updated_at"`
}

func (q *Queries) UpsertAuthor(ctx context.Context, arg UpsertAuthorParams) (UpsertAuthorRow, error) {
	row := q.db.QueryRowContext(ctx, upsertAuthor,
		arg.ID,
		arg.Name,
		arg.Bio,
		arg.Email,
	)
	var i UpsertAuthorRow
	err := row.Scan(&i.ID, &i.Name, &i.UpdatedAt)
	return i, err
}
